public V getWithStampedeProtection(String key) {
    V value = cache.get(key);
    if (value == null) {
        synchronized(this) {
            value = cache.get(key);
            if (value == null) {
                value = database.fetch(key);
                cache.put(key, value);
            }
        }
    }
    return value;
}
